Running command: cat > /app/public/app.js <<'EOF'
'use strict';

const $ = (id) => document.getElementById(id);
const ui = {
  title: $('document-title'), saveState: $('save-state'), revisionState: $('revision-state'), save: $('save-button'),
  undo: $('undo-button'), redo: $('redo-button'), find: $('find-input'), replaceText: $('replace-input'),
  matchState: $('match-state'), findNext: $('find-next-button'), replace: $('replace-button'), replaceAll: $('replace-all-button'),
  historyButton: $('history-button'), historyPanel: $('history-panel'), closeHistory: $('close-history-button'),
  revisionList: $('revision-list'), message: $('message'), editor: $('editor'), canvas: $('editor-canvas'),
  lines: $('line-layer'), selections: $('selection-layer'), carets: $('caret-layer'), cursor: $('cursor-state'),
  selectionState: $('selection-state'), previewBanner: $('preview-banner'), previewLabel: $('preview-label'),
  restorePreview: $('restore-preview-button'), exitPreview: $('exit-preview-button')
};

const state = {
  id: null, title: '', content: '', savedContent: '', baseRevision: 0,
  ranges: [{ anchor: 0, head: 0, goalColumn: null }],
  undo: [], redo: [], lineStarts: [0], lines: [''], charWidth: 8,
  lineHeight: 21, textLeft: 77, dragging: false, dragRange: 0,
  pointer: null, autoscrollFrame: 0, findMatches: [], findIndex: -1,
  preview: null, prePreview: null, conflicted: false
};

function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }
function ordered(range) { return [Math.min(range.anchor, range.head), Math.max(range.anchor, range.head)]; }
function hasSelection(range) { return range.anchor !== range.head; }
function primary() { return state.ranges[0]; }

function rebuildLines() {
  state.lines = state.content.split('\n');
  state.lineStarts = new Array(state.lines.length);
  let offset = 0;
  for (let i = 0; i < state.lines.length; i += 1) {
    state.lineStarts[i] = offset;
    offset += state.lines[i].length + 1;
  }
}

function positionToLineColumn(position) {
  const pos = clamp(position, 0, state.content.length);
  let low = 0;
  let high = state.lineStarts.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    if (state.lineStarts[mid] <= pos) low = mid + 1;
    else high = mid - 1;
  }
  const line = Math.max(0, high);
  return { line, column: pos - state.lineStarts[line] };
}

function lineColumnToPosition(line, column) {
  const safeLine = clamp(line, 0, state.lines.length - 1);
  return state.lineStarts[safeLine] + clamp(column, 0, state.lines[safeLine].length);
}

function normalizeRanges(ranges) {
  const unique = [];
  for (const range of ranges) {
    const normalized = {
      anchor: clamp(range.anchor, 0, state.content.length),
      head: clamp(range.head, 0, state.content.length),
      goalColumn: range.goalColumn ?? null
    };
    const [start, end] = ordered(normalized);
    const duplicate = unique.some((item) => {
      const [itemStart, itemEnd] = ordered(item);
      return start === itemStart && end === itemEnd;
    });
    if (!duplicate) unique.push(normalized);
  }
  return unique.length ? unique : [{ anchor: 0, head: 0, goalColumn: null }];
}

function snapshot() {
  return { content: state.content, ranges: state.ranges.map((range) => ({ ...range })) };
}

function restoreSnapshot(value) {
  state.content = value.content;
  state.ranges = value.ranges.map((range) => ({ ...range }));
  rebuildLines();
  updateFindMatches();
  render();
  revealPrimary();
}

function recordEdit(before) {
  if (before.content === state.content) return;
  state.undo.push(before);
  if (state.undo.length > 200) state.undo.shift();
  state.redo = [];
  state.conflicted = false;
}

function applyEdits(edits) {
  if (state.preview) return showMessage('Exit preview or restore it before editing.');
  const before = snapshot();
  const sorted = edits
    .map((edit, index) => ({ ...edit, index }))
    .sort((a, b) => b.start - a.start || b.end - a.end);
  let content = state.content;
  const results = new Array(edits.length);
  for (const edit of sorted) {
    content = content.slice(0, edit.start) + edit.text + content.slice(edit.end);
    results[edit.index] = edit.start + edit.text.length;
    for (const other of sorted) {
      if (other.start < edit.start && results[other.index] !== undefined) {
        results[other.index] += edit.text.length - (edit.end - edit.start);
      }
    }
  }
  state.content = content;
  rebuildLines();

  // Recalculate each resulting caret against all edits occurring before it.
  state.ranges = edits.map((edit) => {
    let position = edit.start + edit.text.length;
    for (const other of edits) {
      if (other === edit) continue;
      if (other.start < edit.start) position += other.text.length - (other.end - other.start);
    }
    return { anchor: position, head: position, goalColumn: null };
  });
  state.ranges = normalizeRanges(state.ranges);
  recordEdit(before);
  updateFindMatches();
  render();
  revealPrimary();
}

function replaceSelections(text) {
  const edits = state.ranges.map((range) => {
    const [start, end] = ordered(range);
    return { start, end, text };
  });
  applyEdits(edits);
}

function deleteByDirection(direction) {
  const edits = state.ranges.map((range) => {
    let [start, end] = ordered(range);
    if (start === end) {
      if (direction < 0 && start > 0) start -= 1;
      if (direction > 0 && end < state.content.length) end += 1;
    }
    return { start, end, text: '' };
  }).filter((edit) => edit.start !== edit.end);
  if (edits.length) applyEdits(edits);
}

function undo() {
  if (!state.undo.length || state.preview) return;
  state.redo.push(snapshot());
  restoreSnapshot(state.undo.pop());
}
function redo() {
  if (!state.redo.length || state.preview) return;
  state.undo.push(snapshot());
  restoreSnapshot(state.redo.pop());
}

function moveHead(range, key, byWord) {
  const current = positionToLineColumn(range.head);
  if (key === 'ArrowLeft') {
    if (!byWord) return Math.max(0, range.head - 1);
    let pos = range.head;
    while (pos > 0 && /\s/.test(state.content[pos - 1])) pos -= 1;
    while (pos > 0 && /[\p{L}\p{N}_]/u.test(state.content[pos - 1])) pos -= 1;
    return pos;
  }
  if (key === 'ArrowRight') {
    if (!byWord) return Math.min(state.content.length, range.head + 1);
    let pos = range.head;
    while (pos < state.content.length && /[\p{L}\p{N}_]/u.test(state.content[pos])) pos += 1;
    while (pos < state.content.length && /\s/.test(state.content[pos])) pos += 1;
    return pos;
  }
  if (key === 'Home') return state.lineStarts[current.line];
  if (key === 'End') return state.lineStarts[current.line] + state.lines[current.line].length;
  const delta = key === 'ArrowUp' ? -1 : 1;
  const goal = range.goalColumn ?? current.column;
  return lineColumnToPosition(current.line + delta, goal);
}

function navigate(key, extend, byWord) {
  state.ranges = state.ranges.map((range) => {
    const [start, end] = ordered(range);
    let next;
    if (!extend && hasSelection(range) && (key === 'ArrowLeft' || key === 'ArrowRight')) {
      next = key === 'ArrowLeft' ? start : end;
    } else {
      next = moveHead(range, key, byWord);
    }
    const vertical = key === 'ArrowUp' || key === 'ArrowDown';
    const goal = vertical ? (range.goalColumn ?? positionToLineColumn(range.head).column) : null;
    return { anchor: extend ? range.anchor : next, head: next, goalColumn: goal };
  });
  state.ranges = normalizeRanges(state.ranges);
  renderOverlaysAndStatus();
  revealPrimary();
}

function selectAll() {
  state.ranges = [{ anchor: 0, head: state.content.length, goalColumn: null }];
  renderOverlaysAndStatus();
}

function selectedText() {
  return state.ranges.filter(hasSelection).map((range) => {
    const [start, end] = ordered(range);
    return state.content.slice(start, end);
  }).join('\n');
}

function renderLines() {
  const fragment = document.createDocumentFragment();
  let longest = 1;
  state.lines.forEach((text, index) => {
    longest = Math.max(longest, text.length);
    const line = document.createElement('div');
    line.className = 'editor-line';
    const number = document.createElement('span');
    number.className = 'line-number';
    number.textContent = String(index + 1);
    const lineText = document.createElement('span');
    lineText.className = 'line-text';
    lineText.textContent = text || ' ';
    line.append(number, lineText);
    fragment.append(line);
  });
  ui.lines.replaceChildren(fragment);
  ui.canvas.style.height = `${Math.max(state.lines.length * state.lineHeight, ui.editor.clientHeight)}px`;
  ui.canvas.style.width = `${Math.max(state.textLeft + longest * state.charWidth + 30, ui.editor.clientWidth)}px`;
}

function addSelectionBlock(line, startColumn, endColumn, secondary) {
  const block = document.createElement('div');
  block.className = `selection-block${secondary ? ' secondary' : ''}`;
  block.style.top = `${line * state.lineHeight}px`;
  block.style.left = `${state.textLeft + startColumn * state.charWidth}px`;
  block.style.width = `${Math.max(2, (endColumn - startColumn) * state.charWidth)}px`;
  ui.selections.append(block);
}

function renderOverlaysAndStatus() {
  ui.selections.replaceChildren();
  ui.carets.replaceChildren();
  state.ranges.forEach((range, rangeIndex) => {
    const [start, end] = ordered(range);
    if (start !== end) {
      const first = positionToLineColumn(start);
      const last = positionToLineColumn(end);
      for (let line = first.line; line <= last.line; line += 1) {
        const startColumn = line === first.line ? first.column : 0;
        let endColumn = line === last.line ? last.column : state.lines[line].length + 1;
        if (line !== last.line && endColumn === 0) endColumn = 1;
        if (endColumn > startColumn || line !== last.line) addSelectionBlock(line, startColumn, endColumn, rangeIndex > 0);
      }
    }
    const pos = positionToLineColumn(range.head);
    const caret = document.createElement('div');
    caret.className = `caret${rangeIndex ? ' secondary' : ''}`;
    caret.style.top = `${pos.line * state.lineHeight}px`;
    caret.style.left = `${state.textLeft + pos.column * state.charWidth}px`;
    ui.carets.append(caret);
  });

  const pos = positionToLineColumn(primary().head);
  ui.cursor.textContent = `Line ${pos.line + 1}, Column ${pos.column + 1}`;
  const selected = state.ranges.reduce((total, range) => total + Math.abs(range.head - range.anchor), 0);
  const carets = state.ranges.length;
  ui.selectionState.textContent = selected ? `${selected.toLocaleString()} characters selected${carets > 1 ? ` · ${carets} carets` : ''}` : `${carets} caret${carets === 1 ? '' : 's'}`;
  updateControls();
}

function render() {
  renderLines();
  renderOverlaysAndStatus();
}

function isDirty() { return state.content !== state.savedContent; }
function updateControls() {
  const dirty = isDirty();
  ui.save.disabled = !state.id || !dirty || Boolean(state.preview);
  ui.undo.disabled = !state.undo.length || Boolean(state.preview);
  ui.redo.disabled = !state.redo.length || Boolean(state.preview);
  ui.replace.disabled = !ui.find.value || !state.findMatches.length || Boolean(state.preview);
  ui.replaceAll.disabled = !ui.find.value || !state.findMatches.length || Boolean(state.preview);
  ui.revisionState.textContent = `Revision ${state.baseRevision || '—'}`;
  ui.saveState.className = `badge ${state.conflicted ? 'conflict' : dirty ? 'dirty' : 'saved'}`;
  ui.saveState.textContent = state.conflicted ? 'Conflict' : dirty ? 'Unsaved changes' : 'Saved';
}

function revealPrimary() {
  const pos = positionToLineColumn(primary().head);
  const top = pos.line * state.lineHeight;
  const left = state.textLeft + pos.column * state.charWidth;
  if (top < ui.editor.scrollTop) ui.editor.scrollTop = top;
  else if (top + state.lineHeight > ui.editor.scrollTop + ui.editor.clientHeight) ui.editor.scrollTop = top + state.lineHeight - ui.editor.clientHeight;
  if (left < ui.editor.scrollLeft + state.textLeft) ui.editor.scrollLeft = Math.max(0, left - state.textLeft);
  else if (left + state.charWidth > ui.editor.scrollLeft + ui.editor.clientWidth) ui.editor.scrollLeft = left + state.charWidth - ui.editor.clientWidth;
}

function pointToPosition(clientX, clientY) {
  const rect = ui.editor.getBoundingClientRect();
  const documentX = clientX - rect.left + ui.editor.scrollLeft;
  const documentY = clientY - rect.top + ui.editor.scrollTop;
  const line = clamp(Math.floor(documentY / state.lineHeight), 0, state.lines.length - 1);
  const column = Math.round((documentX - state.textLeft) / state.charWidth);
  return lineColumnToPosition(line, column);
}

function wordRange(position) {
  let start = position;
  let end = position;
  const word = /[\p{L}\p{N}_]/u;
  if (start === state.content.length && start) start -= 1;
  const isWord = word.test(state.content[start] || '');
  const matches = (char) => isWord ? word.test(char) : char !== '\n' && !word.test(char);
  while (start > 0 && matches(state.content[start - 1])) start -= 1;
  while (end < state.content.length && matches(state.content[end])) end += 1;
  return { anchor: start, head: end, goalColumn: null };
}

function lineRange(position) {
  const pos = positionToLineColumn(position);
  const start = state.lineStarts[pos.line];
  const end = pos.line < state.lines.length - 1 ? state.lineStarts[pos.line + 1] : state.content.length;
  return { anchor: start, head: end, goalColumn: null };
}

function pointerDown(event) {
  if (event.button !== 0) return;
  if (state.preview) return;
  event.preventDefault();
  ui.editor.focus();
  const position = pointToPosition(event.clientX, event.clientY);
  const addCaret = event.altKey || event.ctrlKey || event.metaKey;
  if (event.detail >= 3) state.ranges = [lineRange(position)];
  else if (event.detail === 2) state.ranges = [wordRange(position)];
  else if (event.shiftKey) primary().head = position;
  else if (addCaret) state.ranges.push({ anchor: position, head: position, goalColumn: null });
  else state.ranges = [{ anchor: position, head: position, goalColumn: null }];
  state.ranges = normalizeRanges(state.ranges);
  state.dragRange = addCaret ? state.ranges.length - 1 : 0;
  state.dragging = event.detail === 1;
  state.pointer = { x: event.clientX, y: event.clientY };
  renderOverlaysAndStatus();
}

function pointerMove(event) {
  if (!state.dragging) return;
  state.pointer = { x: event.clientX, y: event.clientY };
  const range = state.ranges[state.dragRange] || primary();
  range.head = pointToPosition(event.clientX, event.clientY);
  renderOverlaysAndStatus();
  startAutoscroll();
}

function startAutoscroll() {
  if (state.autoscrollFrame) return;
  const tick = () => {
    state.autoscrollFrame = 0;
    if (!state.dragging || !state.pointer) return;
    const rect = ui.editor.getBoundingClientRect();
    let dy = 0;
    let dx = 0;
    if (state.pointer.y < rect.top + 24) dy = -Math.min(35, rect.top + 24 - state.pointer.y);
    else if (state.pointer.y > rect.bottom - 24) dy = Math.min(35, state.pointer.y - rect.bottom + 24);
    if (state.pointer.x < rect.left + state.textLeft) dx = -Math.min(30, rect.left + state.textLeft - state.pointer.x);
    else if (state.pointer.x > rect.right - 20) dx = Math.min(30, state.pointer.x - rect.right + 20);
    if (dx || dy) {
      ui.editor.scrollBy(dx, dy);
      const range = state.ranges[state.dragRange] || primary();
      range.head = pointToPosition(state.pointer.x, state.pointer.y);
      renderOverlaysAndStatus();
      state.autoscrollFrame = requestAnimationFrame(tick);
    }
  };
  state.autoscrollFrame = requestAnimationFrame(tick);
}

function pointerUp() {
  state.dragging = false;
  state.pointer = null;
  if (state.autoscrollFrame) cancelAnimationFrame(state.autoscrollFrame);
  state.autoscrollFrame = 0;
}

function keyDown(event) {
  if (state.preview && event.key !== 'Escape') return;
  const command = event.ctrlKey || event.metaKey;
  if (command && event.key.toLowerCase() === 'a') { event.preventDefault(); selectAll(); return; }
  if (command && event.key.toLowerCase() === 's') { event.preventDefault(); save(); return; }
  if (command && event.key.toLowerCase() === 'z') { event.preventDefault(); event.shiftKey ? redo() : undo(); return; }
  if (command && event.key.toLowerCase() === 'y') { event.preventDefault(); redo(); return; }
  if (command && event.key.toLowerCase() === 'f') { event.preventDefault(); ui.find.focus(); ui.find.select(); return; }
  if (command && ['c', 'x', 'v'].includes(event.key.toLowerCase())) return;
  if (event.key === 'Escape' && state.preview) { exitPreview(); return; }
  if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) {
    event.preventDefault();
    navigate(event.key, event.shiftKey, command && (event.key === 'ArrowLeft' || event.key === 'ArrowRight'));
    return;
  }
  if (event.key === 'Backspace') { event.preventDefault(); deleteByDirection(-1); return; }
  if (event.key === 'Delete') { event.preventDefault(); deleteByDirection(1); return; }
  if (event.key === 'Enter') { event.preventDefault(); replaceSelections('\n'); return; }
  if (event.key === 'Tab') { event.preventDefault(); replaceSelections('  '); return; }
  if (!command && !event.altKey && event.key.length === 1) {
    event.preventDefault();
    replaceSelections(event.key);
  }
}

function updateFindMatches() {
  const query = ui.find.value;
  state.findMatches = [];
  if (query) {
    let from = 0;
    while (from <= state.content.length - query.length) {
      const found = state.content.indexOf(query, from);
      if (found < 0) break;
      state.findMatches.push(found);
      from = found + Math.max(1, query.length);
    }
  }
  if (!state.findMatches.length) state.findIndex = -1;
  else state.findIndex = clamp(state.findIndex, 0, state.findMatches.length - 1);
  ui.matchState.textContent = !query ? 'No search' : !state.findMatches.length ? 'No matches' : `${state.findIndex + 1} of ${state.findMatches.length}`;
  updateControls();
}

function findNext() {
  updateFindMatches();
  if (!state.findMatches.length) return showMessage(ui.find.value ? 'No matches found.' : 'Enter text to find.');
  const currentEnd = Math.max(...state.ranges.map((range) => ordered(range)[1]));
  let index = state.findMatches.findIndex((position) => position >= currentEnd);
  if (index < 0) index = 0;
  if (state.findIndex === index && ordered(primary())[0] === state.findMatches[index]) index = (index + 1) % state.findMatches.length;
  state.findIndex = index;
  const start = state.findMatches[index];
  state.ranges = [{ anchor: start, head: start + ui.find.value.length, goalColumn: null }];
  ui.matchState.textContent = `${index + 1} of ${state.findMatches.length}`;
  renderOverlaysAndStatus();
  revealPrimary();
  ui.editor.focus();
}

function replaceCurrent() {
  const query = ui.find.value;
  if (!query || !state.findMatches.length) return;
  const [start, end] = ordered(primary());
  if (state.content.slice(start, end) !== query) {
    findNext();
    return;
  }
  applyEdits([{ start, end, text: ui.replaceText.value }]);
  findNext();
}

function replaceAll() {
  const query = ui.find.value;
  if (!query || !state.findMatches.length) return;
  const replacement = ui.replaceText.value;
  const edits = state.findMatches.map((start) => ({ start, end: start + query.length, text: replacement }));
  applyEdits(edits);
  showMessage(`Replaced ${edits.length} match${edits.length === 1 ? '' : 'es'}.`, 'info');
}

function showMessage(text, type = 'error') {
  ui.message.textContent = text;
  ui.message.className = `message${type === 'info' ? ' info' : ''}`;
  ui.message.hidden = false;
}
function clearMessage() { ui.message.hidden = true; }

async function request(url, options) {
  const response = await fetch(url, options);
  let data;
  try { data = await response.json(); } catch { data = { error: `Request failed (${response.status}).` }; }
  if (!response.ok) {
    const error = new Error(data.error || `Request failed (${response.status}).`);
    error.status = response.status;
    error.data = data;
    throw error;
  }
  return data;
}

async function save() {
  if (!isDirty() || state.preview) return;
  clearMessage();
  ui.save.disabled = true;
  ui.save.textContent = 'Saving…';
  try {
    const data = await request(`/api/documents/${encodeURIComponent(state.id)}`, {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: state.id, title: state.title, content: state.content, baseRevision: state.baseRevision })
    });
    state.baseRevision = data.document.currentRevision;
    state.savedContent = data.document.content;
    state.conflicted = false;
    showMessage(data.unchanged ? 'Already saved; no duplicate revision was created.' : `Saved revision ${state.baseRevision}.`, 'info');
    updateControls();
    if (!ui.historyPanel.hidden) loadHistory();
  } catch (error) {
    if (error.status === 409) state.conflicted = true;
    showMessage(error.status === 409 ? `${error.message} Latest is revision ${error.data.currentRevision}. Reload to view it; your unsaved text remains here.` : error.message);
    updateControls();
  } finally {
    ui.save.textContent = 'Save';
  }
}

async function loadHistory() {
  try {
    const data = await request(`/api/documents/${encodeURIComponent(state.id)}/revisions`);
    const fragment = document.createDocumentFragment();
    data.revisions.forEach((revision) => {
      const item = document.createElement('li');
      item.className = `revision-item${revision.revisionNumber === state.baseRevision ? ' current' : ''}`;
      const row = document.createElement('div');
      row.className = 'revision-row';
      const label = document.createElement('strong');
      label.textContent = `Revision ${revision.revisionNumber}${revision.revisionNumber === state.baseRevision ? ' · current' : ''}`;
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = 'Preview';
      button.addEventListener('click', () => previewRevision(revision.revisionNumber));
      row.append(label, button);
      const time = document.createElement('div');
      time.className = 'revision-time';
      time.textContent = `${new Date(revision.createdAt).toLocaleString()} · ${revision.contentLength.toLocaleString()} characters`;
      item.append(row, time);
      fragment.append(item);
    });
    ui.revisionList.replaceChildren(fragment);
  } catch (error) { showMessage(error.message); }
}

async function previewRevision(number) {
  if (state.preview) exitPreview(false);
  try {
    const data = await request(`/api/documents/${encodeURIComponent(state.id)}/revisions/${number}`);
    state.prePreview = snapshot();
    state.preview = data.revision;
    state.content = data.revision.content;
    state.ranges = [{ anchor: 0, head: 0, goalColumn: null }];
    rebuildLines();
    render();
    ui.editor.classList.add('previewing');
    ui.previewBanner.hidden = false;
    ui.previewLabel.textContent = `Previewing revision ${number}`;
    updateFindMatches();
  } catch (error) { showMessage(error.message); }
}

function exitPreview(renderEditor = true) {
  if (!state.preview || !state.prePreview) return;
  const previous = state.prePreview;
  state.preview = null;
  state.prePreview = null;
  ui.previewBanner.hidden = true;
  ui.editor.classList.remove('previewing');
  if (renderEditor) restoreSnapshot(previous);
  else {
    state.content = previous.content;
    state.ranges = previous.ranges;
    rebuildLines();
  }
}

function restorePreview() {
  if (!state.preview || !state.prePreview) return;
  const restored = state.preview;
  const before = state.prePreview;
  state.preview = null;
  state.prePreview = null;
  ui.previewBanner.hidden = true;
  ui.editor.classList.remove('previewing');
  state.content = restored.content;
  state.ranges = [{ anchor: 0, head: 0, goalColumn: null }];
  rebuildLines();
  recordEdit(before);
  updateFindMatches();
  render();
