async function call(path, options={}) { const r=await fetch(base+path, options); return {status:r.status, body:await r.json()}; }
(async()=>{
  const original=(await call('/api/documents/incident-alpha')).body.document;
  const headers={'content-type':'application/json'};
  const changed={id:original.id,title:original.title,content:original.content+'\nVerification edit',baseRevision:1};
